1	/*
2	 * AIThinkingPart — the model's reasoning (Figma 761:1345).
3	 *
4	 * ## behavior
5	 * - `thinking`: the label shimmers (ShimmerText, re-based by
6	 *   `ds-chat-thinking-shimmer`) and a transcript, if given, streams inline and
7	 *   is always visible — there is nothing to toggle while it is live.
8	 * - `thought` with a transcript: the row becomes a disclosure. The chevron is
9	 *   revealed on hover and stays while open; the settled label and meta rest at
10	 *   text-secondary and the label lifts to text-primary on hover; the transcript collapses with a
11	 *   grid-rows transition timed by the motion scale (`--ui-motion-*`).
12	 * - `thought` without a transcript: a plain settled row.
13	 * - Open state is controllable (`open` / `onOpenChange`) or uncontrolled
14	 *   (`defaultOpen`). It is the only state this component owns.
15	 * - Transcript colour is inherited by `ds-chat-prose`: tertiary while live,
16	 *   secondary once opened, as Figma draws them.
17	 * - Root attributes: `data-phase` is always the `AIThinkingPartState`.
18	 *   `data-state` is the phase on the `thinking` row and on a `thought` row
19	 *   without a transcript, but the disclosure state (`open` / `closed`) on an
20	 *   expandable `thought` row, where the `[data-state="open"]` reveal and lift
21	 *   rules in dooph-component-tokens.css read it. Style on `data-phase` to
22	 *   target a phase; do not change what `data-state` holds.
23	 *
24	 * ## constraints
25	 * - A transcript is "available" exactly when `children` is given. Providers that
26	 *   never stream reasoning text simply pass none, and the row stays static.
27	 * - `label` and `meta` are the consumer's copy ("Thinking", "Thought for 26s",
28	 *   "3s • 743 tokens"). No timer lives here — the consumer ticks elapsed time,
29	 *   so it can start counting whenever it chooses.
30	 */
31	"use client";
32	
33	import {
34	  forwardRef,
35	  useCallback,
36	  useId,
37	  useState,
38	  type HTMLAttributes,
39	  type ReactNode,
40	} from "react";
41	import { cn } from "../../utils/cn";
42	import { BodyText } from "../Text";
43	import { ShimmerText } from "../AnimatedText";
44	import { Button } from "../Button";
45	import { ButtonVariant } from "../Button/constants";
46	import { DropdownIcon, IconSize } from "../Icons";
47	import { AIThinkingPartState } from "./constants";
48	
49	export interface AIThinkingPartProps
50	  extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
51	  state?: AIThinkingPartState;
52	  /** "Thinking" while live, "Thought for 26s" once settled — the consumer's copy. */
53	  label: ReactNode;
54	  /** Secondary detail beside the label, e.g. "3s • 743 tokens". */
55	  meta?: ReactNode;
56	  /** The reasoning transcript. Its presence is what makes a settled row expandable. */
57	  children?: ReactNode;
58	  /**
59	   * Animate transcript blocks in as they arrive (see AITextPart). Applies to
60	   * the live `thinking` transcript only — a settled transcript never animates.
61	   */
62	  streamingAnimation?: boolean;
63	  open?: boolean;
64	  defaultOpen?: boolean;
65	  onOpenChange?: (open: boolean) => void;
66	}
67	
68	const AIThinkingPart = forwardRef<HTMLDivElement, AIThinkingPartProps>(
69	  (
70	    {
71	      state = AIThinkingPartState.thinking,
72	      label,
73	      meta,
74	      children,
75	      streamingAnimation = false,
76	      open: openProp,
77	      defaultOpen = false,
78	      onOpenChange,
79	      className,
80	      ...props
81	    },
82	    ref,
83	  ) => {
84	    const transcriptId = useId();
85	    const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
86	    const open = openProp ?? uncontrolledOpen;
87	    const setOpen = useCallback(
88	      (next: boolean) => {
89	        if (openProp === undefined) setUncontrolledOpen(next);
90	        onOpenChange?.(next);
91	      },
92	      [openProp, onOpenChange],
93	    );
94	
95	    const isThinking = state === AIThinkingPartState.thinking;
96	    const hasTranscript = children != null && children !== false;
97	    const hasMeta = meta != null && meta !== false;
98	
99	    const metaNode = hasMeta ? (
100	      <BodyText className="min-w-0 truncate whitespace-nowrap text-text-secondary">
101	        {meta}
102	      </BodyText>
103	    ) : null;
104	
105	    if (isThinking) {
106	      return (
107	        <div
108	          ref={ref}
109	          data-state={state}
110	          data-phase={state}
111	          className={cn(
112	            "flex w-full min-w-0 flex-col gap-rg px-sm py-xxs",
113	            className,
114	          )}
115	          {...props}
116	        >
117	          <div className="flex min-w-0 select-none items-center gap-rg">
118	            <BodyText
119	              as={ShimmerText}
120	              className="ds-chat-thinking-shimmer shrink-0 whitespace-nowrap"
121	            >
122	              {label}
123	            </BodyText>
124	            {metaNode}
125	          </div>
126	          {hasTranscript ? (
127	            <BodyText
128	              as="div"
129	              data-streaming-animation={streamingAnimation || undefined}
130	              className="ds-chat-prose min-w-0 pl-sm text-text-tertiary wrap-break-word"
131	            >
132	              {children}
133	            </BodyText>
134	          ) : null}
135	        </div>
136	      );
137	    }
138	
139	    const labelNode = (
140	      <BodyText
141	        className={cn(
142	          "shrink-0 whitespace-nowrap text-text-secondary",
143	          hasTranscript && "ds-chat-lift",
144	        )}
145	      >
146	        {label}
147	      </BodyText>
148	    );
149	
150	    if (!hasTranscript) {
151	      return (
152	        <div
153	          ref={ref}
154	          data-state={state}
155	          data-phase={state}
156	          className={cn(
157	            "flex w-full min-w-0 select-none items-center gap-rg px-sm py-xxs",
158	            className,
159	          )}
160	          {...props}
161	        >
162	          {labelNode}
163	          {metaNode}
164	        </div>
165	      );
166	    }
167	
168	    const openState = open ? "open" : "closed";
169	
170	    return (
171	      <div
172	        ref={ref}
173	        data-state={openState}
174	        data-phase={state}
175	        className={cn(
176	          "ds-chat-reveal-root flex w-full min-w-0 flex-col",
177	          className,
178	        )}
179	        {...props}
180	      >
181	        <Button
182	          variant={ButtonVariant.text}
183	          data-state={openState}
184	          aria-expanded={open}
185	          aria-controls={transcriptId}
186	          onClick={() => setOpen(!open)}
187	          className="h-auto w-full justify-start gap-rg border-0 px-sm py-xxs"
188	        >
189	          {labelNode}
190	          {metaNode}
191	          {/* Down while closed, up while open — ds-chat-chevron rotates on the
192	              button's data-state, timed by the motion scale. */}
193	          <DropdownIcon
194	            size={IconSize.rg}
195	            aria-hidden
196	            className="ds-chat-chevron ds-chat-reveal shrink-0 text-ghost-fg-active"
197	          />
198	        </Button>
199	        <div
200	          id={transcriptId}
201	          data-state={openState}
202	          inert={!open}
203	          className="ds-chat-disclosure"
204	        >
205	          <div>
206	            {/* px-sm matches the row's own inset; pl-sm indents the transcript
207	                under the label, as the live variant does. */}
208	            <BodyText
209	              as="div"
210	              className="ds-chat-prose mx-sm min-w-0 pb-xxs pl-sm pt-rg text-text-secondary wrap-break-word"
211	            >
212	              {children}
213	            </BodyText>
214	          </div>
215	        </div>
216	      </div>
217	    );
218	  },
219	);
220	AIThinkingPart.displayName = "AIThinkingPart";
221	
222	export { AIThinkingPart };
223

1	@layer ds.tokens, ds.expression;
2	
3	/*
4	 * dooph Design System — Token Layer
5	 *
6	 * Theming contract:
7	 * — Light palette: `:root` and `.light` (same declarations). Default look for
8	 *   apps that omit theme classes or force `class="light"` (e.g. next-themes).
9	 * — Dark palette: `.dark` on the app root (typically `<html>`). Your theme
10	 *   provider decides when `.light` vs `.dark` applies (manual toggle, saved
11	 *   preference, three-way light/dark/system, etc.).
12	 * — There is NO `prefers-color-scheme` remapping here: system mode is the
13	 *   consuming app's job (providers add/remove `.dark` from OS preference).
14	 *
15	 * Authority — cascade layers, so precedence never depends on file order or
16	 * selector specificity. Everything below sits in two layers:
17	 *   ds.tokens      the DS defaults (light, dark, reduced motion)
18	 *   ds.expression  the expression presets ([data-ds-expression="…"])
19	 * A consuming app's own tokens.css is UNLAYERED, so it always wins:
20	 *   your tokens.css > the expression preset > DS defaults.
21	 * Override `--ui-*` there, targeting `:root` / `.light` / `.dark` as needed —
22	 * never hardcoded in components. Import order does not matter.
23	 *
24	 * Expression tokens: one per expressive DETAIL inside a practical component
25	 * (e.g. the dropdown caret's shape). Each line ends in an `expression`
26	 * marker comment, is read only through a `.ds-expr-*` helper, and has its
27	 * neutral value in the practical preset at the end of this file. Components
28	 * never set them.
29	 * Checked by the lint check "expression tokens set or read outside the
30	 * expression system".
31	 */
32	
33	@layer ds.tokens {
34	
35	:root,
36	.light {
37	  /* ── Colors ─────────────────────────────────────────────────────────── */
38	
39	  /* Primary (dark neutral) — borders alias bg per state (Figma) */
40	  --ui-color-primary: #171717;
41	  --ui-color-primary-border: var(--ui-color-primary);
42	  --ui-color-primary-hover: #2c2c2c;
43	  --ui-color-primary-border-hover: var(--ui-color-primary-hover);
44	  --ui-color-primary-active: #3d3d3d;
45	  --ui-color-primary-border-active: var(--ui-color-primary-active);
46	  --ui-color-primary-foreground: #ffffff;
47	  /* Disabled paints alias secondary so all solid buttons share one disabled look;
48	   * token names stay so consumers can still override primary-disabled alone. */
49	  --ui-color-primary-disabled: var(--ui-color-secondary-disabled);
50	  --ui-color-primary-border-disabled: var(--ui-color-secondary-border-disabled);
51	
52	  /* Secondary (light surface) — borders are distinct Figma literals */
53	  --ui-color-secondary: #fdfdfd;
54	  --ui-color-secondary-border: #e2e3e4;
55	  --ui-color-secondary-hover: #efefef;
56	  --ui-color-secondary-border-hover: #e2e3e4;
57	  --ui-color-secondary-active: #e3e3e3;
58	  --ui-color-secondary-border-active: #e2e3e4;
59	  --ui-color-secondary-foreground: #161616;
60	  --ui-color-secondary-disabled: #f5f5f5;
61	  --ui-color-secondary-border-disabled: #e9e9e9;
62	
63	  /* Prominent (deep violet) — Figma ButtonProminent/*. Borders alias bg per
64	   * state. Its own paints are mode-invariant, so they have no .dark override
65	   * (the two disabled aliases are repeated in the .dark alias group): the
66	   * Figma group carries identical values in both modes, INCLUDING the
67	   * content colour. That last part is worth stating because the Figma export
68	   * aliases the content to Text/text-inverted, which flips to black in dark —
69	   * black on #340fd9 is 2.2:1 and unreadable, and the export's own resolved
70	   * values report white for both modes. White is the intended paint; do not
71	   * "fix" this into an inverted alias. */
72	  --ui-color-prominent: #340fd9;
73	  --ui-color-prominent-border: var(--ui-color-prominent);
74	  --ui-color-prominent-hover: #2406ac;
75	  --ui-color-prominent-border-hover: var(--ui-color-prominent-hover);
76	  --ui-color-prominent-active: #1a0189;
77	  --ui-color-prominent-border-active: var(--ui-color-prominent-active);
78	  --ui-color-prominent-foreground: #ffffff;
79	  /* Disabled aliases secondary, matching every other solid button (Figma). */
80	  --ui-color-prominent-disabled: var(--ui-color-secondary-disabled);
81	  --ui-color-prominent-border-disabled: var(
82	    --ui-color-secondary-border-disabled
83	  );
84	
85	  /* Danger — the raw destructive palette (Figma danger-primary / -secondary).
86	   * Mode-invariant, so no .dark override. */
87	  --ui-color-danger-primary: #ea3f3f;
88	  --ui-color-danger-secondary: #ff5858;
89	
90	  /* Danger button (Figma ButtonDanger/*) — a full state family so consumers can
91	   * retune the danger button without touching the secondary family it defaults
92	   * to. Every value is an ALIAS, so they follow the secondary family per mode;
93	   * they are repeated in the .dark alias group so nested `.dark` regions
94	   * re-resolve them. Override any one of them to break that link. */
95	  --ui-color-danger: var(--ui-color-secondary);
96	  --ui-color-danger-border: var(--ui-color-secondary-border);
97	  --ui-color-danger-hover: var(--ui-color-danger-secondary);
98	  --ui-color-danger-border-hover: var(--ui-color-danger-secondary);
99	  --ui-color-danger-active: var(--ui-color-danger-primary);
100	  --ui-color-danger-border-active: var(--ui-color-danger-primary);
101	  --ui-color-danger-foreground: var(--ui-color-danger-primary);
102	  --ui-color-danger-foreground-active: var(--ui-color-secondary-foreground);
103	  --ui-color-danger-disabled: var(--ui-color-secondary-disabled);
104	  --ui-color-danger-border-disabled: var(--ui-color-secondary-border-disabled);
105	
106	  /* Ghost (no rest bg; hover/active are translucent overlays) */
107	  --ui-color-ghost-foreground: var(--ui-color-text);
108	  --ui-color-ghost-hover: rgba(0, 0, 0, 0.04);
109	  --ui-color-ghost-active: rgba(0, 0, 0, 0.08);
110	  --ui-color-ghost-foreground-active: #161616;
111	
112	  /* Surfaces (Figma: surface-page / surface-primary / surface-secondary) */
113	  --ui-color-surface-page: #fdfeff;
114	  --ui-color-surface-primary: #ffffff;
115	  --ui-color-surface-secondary: #fcfcfc;
116	
117	  /* Text selection (::selection). The package ships only the tokens — applying
118	     them is a global, app-owned decision; use the .ds-selection opt-in class or
119	     write your own ::selection rule.
120	
121	     Aliased to the primary button pair, so a selection reads as a primary
122	     surface and follows a rebrand for free. Note this inverts with the palette
123	     (dark-on-light in light mode, light-on-dark in dark) because primary does;
124	     override both tokens if you need a fixed colour. Repeated in the .dark alias
125	     group so a nested .dark region re-resolves it. */
126	  --ui-color-selection: var(--ui-color-primary);
127	  --ui-color-selection-foreground: var(--ui-color-primary-foreground);
128	
129	  /* Modals */
130	  --ui-color-modal-surface: #fdfdfd;
131	  --ui-color-modal-backdrop: rgba(0, 0, 0, 0.35);
132	
133	  /* Tooltips */
134	  --ui-color-tooltip-inverse-surface: var(--ui-color-primary);
135	  --ui-color-tooltip-inverse-text: var(--ui-color-primary-foreground);
136	  --ui-color-tooltip-inverse-border: var(--ui-color-primary);
137	  --ui-color-tooltip-matching-surface: var(--ui-color-secondary);
138	  --ui-color-tooltip-matching-text: var(--ui-color-secondary-foreground);
139	  --ui-color-tooltip-matching-border: var(--ui-color-border-primary);
140	
141	  /* Borders (Figma: border-primary / border-secondary; popovers is the DS name
142	   * for Figma modal-border, shared by modal/menu/toast panels) */
143	  --ui-color-border-primary: #dddddd;
144	  --ui-color-border-secondary: #dfdfdf;
145	  --ui-color-border-popovers: #ebebeb;
146	  --ui-color-input-border-focus: var(--ui-color-prominent-border-hover);
147	  /* CTAButton padded outline ring (primary variant only) */
148	  --ui-color-border-cta: rgba(56, 56, 56, 0.5);
149	  --ui-color-input-border-hover: #b4b4b4;
150	  --ui-color-input-border-danger-focus: var(--ui-color-danger-primary);
151	
152	  /* Text */
153	  --ui-color-text: #161616;
154	  --ui-color-text-secondary: #4a4a4a;
155	  --ui-color-text-tertiary: #606060;
156	
157	  /* Focus rings (Figma: Inputs/focus-ring-prominent|-primary|-danger). Each is
158	   * its source paint at a fixed alpha: prominent = button-prominent-hover in
159	   * light and button-prominent (rest) in dark, primary = button-primary,
160	   * danger = danger-primary. They are literal rgba() rather than color-mix()
161	   * over the source token because a consumer overriding, say,
162	   * --ui-color-prominent should be able to retune the ring independently. */
163	  /* Focus-ring outline width (Figma buttonSizes/focus-ring-spread), and the small
164	   * step for compact controls such as Checkbox, where 4px reads as huge. */
165	  --ui-focus-ring-width: 4px;
166	  --ui-focus-ring-width-sm: 2px;
167	  --ui-color-focus-ring-prominent: rgba(36, 6, 172, 0.35);
168	  --ui-color-focus-ring-primary: rgba(23, 23, 23, 0.25);
169	  --ui-color-focus-ring-danger: rgba(234, 63, 63, 0.35);
170	
171	  /* Prominent identity (Figma: color-prominent / -alt / -ter) — the
172	   * brand-identity trio, distinct from the --ui-color-prominent BUTTON family
173	   * above. All three are mode-invariant: none has a dark value, and #44c0e5
174	   * is `-ter` in its own right, not a dark `-alt`. */
175	  --ui-prominent-color: #390ef8;
176	  --ui-prominent-color-alt: #13c29f;
177	  --ui-prominent-color-ter: #44c0e5;
178	
179	  /* AI model marks (Figma ai-models/*). Brand colours for third-party model
180	   * providers — identity paints for a badge or icon, not a UI role, so no
181	   * component reads them by default. openai and spacexai are the two that
182	   * inverse per mode. */
183	  --ui-color-ai-anthropic: #e48844;
184	  --ui-color-ai-gemini: #154bff;
185	  --ui-color-ai-openai: #000000;
186	  --ui-color-ai-spacexai: #000000;
187	
188	  /* ── Motion ──────────────────────────────────────────────────────────────
189	   * One scale for the whole system: every transition and animation in the
190	   * package reads a duration and a curve from here, so retuning one token
191	   * retunes that step everywhere. Components consume it through the ds-motion-*
192	   * helpers and through var() inside CSS helpers — never through duration-N /
193	   * ease-* utilities or inline timing. A component keeps a motion token of its
194	   * own only when the value cannot sit on the scale: loops, staggers and the
195	   * generated shape-morph spring. Reduced motion is the single
196	   * `prefers-reduced-motion` block at the end of this file.
197	   *
198	   *   fast    — state feedback (hover, press, focus colour); small overlays in
199	   *             and out (menu, tooltip, popover, toast); quick swaps.
200	   *   base    — large overlay in and out (modal in, sheet out); disclosure;
201	   *             content swap out; small transforms.
202	   *   slow    — content swap in; sheet in; progress fills.
203	   *   slower  — reveals; chat streaming.
204	   *   slowest — expressive hover (underline link). */
205	  --ui-motion-duration-fast: 150ms;
206	  --ui-motion-duration-base: 200ms;
207	  --ui-motion-duration-slow: 300ms;
208	  --ui-motion-duration-slower: 420ms;
209	  --ui-motion-duration-slowest: 600ms;
210	  /*   standard — starts and ends on screen: state feedback, fades, progress.
211	   *   enter    — the house curve: entering, swapping in, expressive moves,
212	   *              glides. A long deceleration that settles.
213	   *   exit     — leaving: overlay exits, swap out. Accelerates away.
214	   *   linear   — loops (spinners, shimmer). */
215	  --ui-motion-ease-standard: cubic-bezier(0.4, 0, 0.2, 1);
216	  --ui-motion-ease-enter: cubic-bezier(0.32, 0.72, 0, 1);
217	  --ui-motion-ease-exit: cubic-bezier(0.4, 0, 1, 1);
218	  --ui-motion-ease-linear: linear;
219	  /* Loop cycle times are not transitions, so they sit off the scale and are
220	   * NOT collapsed under reduced motion — each loop's own reduce rule stops it
221	   * or swaps in a static frame instead. */
222	  --ui-shimmer-duration: 2000ms;
223	  /* LoadingSpinner. `duration` is one flat-arc dash cycle (Material's
224	   * circular indeterminate: the arc grows, then its tail chases the head
225	   * round and it shrinks to a dot). `rotate-duration` is one constant turn of
226	   * the flat variant's arc group, a separate loop. Both are Material's
227	   * 1.4s. `spokes-duration` is one turn of the spokes and star variants at
228	   * the `rg` size; the component scales it per size by a geometry factor, so
229	   * retuning this retunes all four sizes together. */
230	  --ui-spinner-duration: 1400ms;
231	  --ui-spinner-rotate-duration: 1400ms;
232	  --ui-spinner-spokes-duration: 1800ms;
233	
234	  /* Text shimmer (ShimmerText) */
235	  --ui-shimmer-base: var(--ui-color-text-tertiary);
236	  --ui-shimmer-highlight: color-mix(
237	    in srgb,
238	    var(--ui-color-text-tertiary) 35%,
239	    transparent
240	  );
241	
242	  /* AI chat parts (AIToolPart, AIThinkingPart, AITurnSummary, AIPromptInput…).
243	   *
244	   * The two shimmer pairs RE-BASE ShimmerText rather than restyling it: a
245	   * working tool row reads at full ghost-active weight, the thinking row at the
246	   * quieter text-secondary weight, the colour a settled thinking label rests at
247	   * (Figma 761:1330 / 761:1346). The highlight keeps the
248	   * package's own base-at-35% formula so a consumer retuning either base keeps
249	   * the sheen in proportion. */
250	  --ui-chat-tool-shimmer-base: var(--ui-color-ghost-foreground-active);
251	  --ui-chat-tool-shimmer-highlight: color-mix(
252	    in srgb,
253	    var(--ui-color-ghost-foreground-active) 35%,
254	    transparent
255	  );
256	  --ui-chat-thinking-shimmer-base: var(--ui-color-text-secondary);
257	  --ui-chat-thinking-shimmer-highlight: color-mix(
258	    in srgb,
259	    var(--ui-color-text-secondary) 35%,
260	    transparent
261	  );
262	  /* `streamingAnimation`: each block of prose rises out of a blur as it
263	   * arrives. `blur` is px on purpose — a lens effect, not a typographic
264	   * measure (the roll's blur, --ui-roll-change-blur, is em because it must
265	   * stay inside a clip box that scales with the type). Its timing, like the
266	   * hover reveal's and the transcript disclosure's, is on the motion scale. */
267	  --ui-chat-stream-blur: 3px;
268	  --ui-chat-stream-rise: 4px;
269	  /* The prompt textarea grows with its content up to this, then scrolls. CSS
270	   * max-height applies the cap and the component only sets height =
271	   * scrollHeight, so this token is the only place the cap lives. */
272	  --ui-chat-prompt-max-height: 300px;
273	  /* The provider swatch in AIModelSelectItem (Figma 761:2073). */
274	  --ui-chat-model-swatch-size: 10px;
275	  --ui-chat-model-swatch-radius: 3px;
276	  /* AIModelTooltipContent panel (Figma 761:2843). */
277	  --ui-width-chat-model-tooltip: 242px;
278	  /* Inline code inside ds-chat-prose. */
279	  --ui-chat-prose-code-radius: 4px;
280	  /* Links and blockquotes inside ds-chat-prose. */
281	  --ui-chat-prose-link-offset: 3px;
282	  --ui-chat-prose-quote-border-width: 2px;
283	
