894	/* ── Reduced motion — the ONE place it is handled ───────────────────────────
895	 * Every transition and animation in the package reads its duration from the
896	 * motion scale, so collapsing the scale here makes the whole system instant.
897	 * A component carries its own reduce rule only where this collapse cannot
898	 * reach: a loop or an off-scale duration (the shimmer, the spinners, the
899	 * shape-morph spring and the dropdown caret that rides it), or motion that
900	 * must become a static frame rather than a shorter one (RollHover).
901	 *
902	 * 1ms, NOT 0ms, and that is load-bearing: a 0ms transition never fires
903	 * `transitionrun` or `transitionend`, and several components hang real work
904	 * off those events (RevealChangeText swaps its content and calls `onSettled`
905	 * on `transitionend`; MorphRotationShape starts sampling on `transitionrun`).
906	 * At 0ms they would strand content on screen. 1ms reads as instant and still
907	 * fires every event.
908	 *
909	 * Staggers go to zero so nothing waits on a delay. Loop cycle times
910	 * (--ui-shimmer-duration, --ui-shape-morph-*) are deliberately absent: a loop
911	 * at 1ms would strobe, so each loop's own reduce rule stops it or shows a
912	 * static frame instead.
913	 *
914	 * `.light` is listed beside `:root` because it redeclares the scale; without
915	 * it a `.light` subtree would quietly restore full-length motion.
916	 *
917	 * `!important` is deliberate and load-bearing: these tokens live in
918	 * `@layer ds.tokens`, and a consumer's UNLAYERED override (e.g. a product
919	 * tuning --ui-motion-duration-fast) would otherwise beat this block and give
920	 * reduced-motion users full animations. A layered !important outranks every
921	 * unlayered normal declaration, so the user's accessibility setting always
922	 * wins. Do not remove it. */
923	@media (prefers-reduced-motion: reduce) {
924	  :root,
925	  .light {
926	    --ui-motion-duration-fast: 1ms !important;
927	    --ui-motion-duration-base: 1ms !important;
928	    --ui-motion-duration-slow: 1ms !important;
929	    --ui-motion-duration-slower: 1ms !important;
930	    --ui-motion-duration-slowest: 1ms !important;
931	    --ui-roll-hover-stagger: 0ms !important;
932	    --ui-rolling-digits-stagger: 0ms !important;
933	  }
934	}
935	
936	/* ── Expression details — DS defaults (the signature look) ──────────────────
937	 * Declared on :root ONLY, not beside `.light`/`.dark`: a theme-class subtree
938	 * must never quietly restore a detail the practical preset turned off. */
939	:root {
940	  /* DropdownCaret shape: 1 = the morphing shape behind the chevron, in its
941	   * square; 0 = a plain chevron, no shape and no frame around it. Values in
942	   * between interpolate size and colour; 0 and 1 are the designed settings. */
943	  --ui-caret-shape-scale: 1; /* expression */
944	  /* DropdownCaret hover lean (a fraction of one step, like
945	   * --ui-shape-morph-nudge, which it follows by default); 0 = no lean. */
946	  --ui-caret-nudge: var(--ui-shape-morph-nudge); /* expression */
947	}
948	
949	} /* @layer ds.tokens */
950	
951	/* ── Expression presets ─────────────────────────────────────────────────────
952	 * A product-level setting: put the attribute on the root element —
953	 * `<html data-ds-expression="practical">` in a Next.js app/layout.tsx, or
954	 * index.html in Vite. Nesting works ("nearest ancestor wins") but is
955	 * discouraged. Every expression-marked token above MUST appear here with
956	 * its neutral value. A product's own unlayered tokens.css still beats this. */
957	@layer ds.expression {
958	  [data-ds-expression="practical"] {
959	    --ui-caret-shape-scale: 0;
960	    --ui-caret-nudge: 0;
961	  }
962	}
