463	  /* RollHoverText — per-character 3D barrel roll on hover. Two identical faces
464	   * per glyph; the offscreen face is hidden by opacity + blur rather than by
465	   * overflow clipping, so descenders (g, y, p, j) are never cut and the
466	   * component stays safe in inline body text.
467	   *
468	   * transition (not @keyframes) is load-bearing: interrupting a transition
469	   * retargets from the current computed value, which is what lets an un-hover
470	   * mid-roll reverse from wherever the letter currently sits. */
471	  .ds-roll-hover {
472	    display: inline;
473	  }
