482	    perspective: var(--ui-roll-hover-perspective);
483	  }
484	  /* The barrel radius lives in the ROTATION AXIS (transform-origin's z), not in a
485	   * translateZ on the faces. Pushing the faces forward with translateZ would put
486	   * them closer to the viewer, and perspective would magnify them ~32% at rest —
487	   * every glyph would overflow its own cell and collide with its neighbours.
