1087	   * The content keeps its natural width while the slot around it is 0 wide
1088	   * because it is `flex-shrink: 0` and `nowrap`. This is deliberately NOT a
1089	   * `grid-template-columns: 1fr -> 0fr` slot: that sizes rows fine, but for a
1090	   * COLUMN in a shrink-to-fit container the `overflow: hidden` item has an
1091	   * automatic minimum of 0, so `1fr` has no free space to claim and collapses
1092	   * the content to nothing.
1093	   *
1094	   * Timing is on the motion scale, one shared `enter` curve. The reveal
1095	   * (`slower`) is deliberately slower than a roll: it is motion the eye is
1096	   * meant to follow. The collapse (`slow`) is shorter because tucking away is
1097	   * the half nobody needs to read, and because a value CHANGE runs both back
1098	   * to back. One curve, unlike the roll's split pair: both halves are the SAME
1099	   * slot moving, and an accelerating collapse reads as the content being
1100	   * yanked rather than tucked. */
1101	  .ds-reveal-change {
1102	    display: inline-flex;
1103	    align-items: center;
1104	    justify-content: flex-end;
1105	    overflow: hidden;
1106	    width: 0;
1107	    transition: width var(--ui-motion-duration-slow)
1108	      var(--ui-motion-ease-enter);
1109	  }
1110	  .ds-reveal-change[data-direction="right"] {
1111	    justify-content: flex-start;
1112	  }
1113	  /* --ds-reveal-change-width is the measured natural width of the content, set
1114	   * by the component. `auto` is the pre-measurement fallback (first paint, SSR)
1115	   * so the slot is never briefly empty; nothing animates on that first render. */
1116	  .ds-reveal-change[data-open="true"] {
1117	    width: var(--ds-reveal-change-width, auto);
1118	    transition-duration: var(--ui-motion-duration-slower);
1119	  }
1120	  .ds-reveal-change-content {
1121	    display: inline-flex;
1122	    flex-shrink: 0;
1123	    align-items: center;
1124	    white-space: nowrap;
1125	  }
1126	
1127	  /* Reduced motion still needs the transition to RUN, just instantly: the
1128	   * content swap at the end of a collapse and the `onSettled` callback both
1129	   * hang off transitionend, and `transition: none` would starve them —
1130	   * stranding the outgoing content on screen forever. The global block in
1131	   * tokens.css collapses the scale to a non-zero instant for exactly this
1132	   * reason, so no rule is needed here. Same trade the rolling text makes. */
1133	}
