1178	@keyframes ds-shimmer {
1179	  from { background-position: 150% center; }
1180	  to   { background-position: -50% center; }
1181	}
1182	/* --ds-roll-dir (default 1 = downward) flips the travel: RollChangeText sets -1
1183	 * for upward. The old face exits in the travel direction; the new face enters
1184	 * from the opposite side. Depth and blur come from --ui-roll-change-*; the
1185	 * mid-point blur is derived from the same token so the two cannot drift. */
