1190	    opacity: 0;
1191	  }
1192	}
1193	@keyframes ds-roll-in {
1194	  from {
1195	    transform: translateY(calc(var(--ds-roll-dir, 1) * -1 * var(--ui-roll-change-depth)));
1196	    filter: blur(var(--ui-roll-change-blur));
1197	    opacity: 0;
1198	  }
1199	  60%  { filter: blur(calc(var(--ui-roll-change-blur) * 0.375)); }
1200	  to   { transform: translateY(0); filter: blur(0); opacity: 1; }
1201	}
1202	/* FadeChangeText — ds-roll-out/-in minus the blur. Same --ds-roll-dir sign
1203	 * convention; depth from --ui-fade-change-depth.
1204	 *
1205	 * Opacity runs on its OWN keyframe offsets, not the travel's: the old face is
1206	 * gone by 50% of its roll, the new face holds at 0 for the first 30% of its
1207	 * roll. Sharing the travel's curve (as the blurred roll does) left both faces
1208	 * near-opaque at once — the in-ease is decelerating — and without blur to mask
1209	 * it the two words visibly stacked with no fade at all. Transform is only
1210	 * given at 0%/100%, so it still interpolates as one continuous curve. The
1211	 * offsets are literal because keyframe selectors cannot read var(). */
