1213	  50% { opacity: 0; }
1214	  to {
1215	    transform: translateY(calc(var(--ds-roll-dir, 1) * var(--ui-fade-change-depth)));
1216	    opacity: 0;
1217	  }
1218	}
1219	@keyframes ds-fade-change-in {
1220	  from {
1221	    transform: translateY(calc(var(--ds-roll-dir, 1) * -1 * var(--ui-fade-change-depth)));
1222	    opacity: 0;
1223	  }
1224	  30% { opacity: 0; }
1225	  to { transform: translateY(0); opacity: 1; }
1226	}
