1234	  from { width: 0; }
1235	}
1236	@keyframes ds-rolling-digits-out {
1237	  to { width: 0; }
1238	}
1239	@keyframes ds-rolling-digits-fade-in {
1240	  from { opacity: 0; }
1241	}
1242	@keyframes ds-rolling-digits-fade-out {
1243	  to { opacity: 0; }
1244	}
