1253	  0%     { background-size: 100% var(--ds-underline-thickness, var(--ui-underline-link-thickness)); background-position-x: 100%; }
1254	  50%    { background-size: 0% var(--ds-underline-thickness, var(--ui-underline-link-thickness));   background-position-x: 100%; }
1255	  50.01% { background-size: 0% var(--ds-underline-thickness, var(--ui-underline-link-thickness));   background-position-x: 0%; }
1256	  100%   { background-size: 100% var(--ds-underline-thickness, var(--ui-underline-link-thickness)); background-position-x: 0%; }
1257	}
