287	    stroke-opacity: clamp(0, var(--ds-pi-c) * var(--ds-pi-progress) * 1000000, 1);
288	  }
289	  .ds-progress-ring-track {
290	    --ds-pi-gap-now: calc(var(--ds-pi-gap) * var(--ds-pi-gap-on));
291	    --ds-pi-track-len: calc(var(--ds-pi-c) * (1 - var(--ds-pi-progress)) - 2 * var(--ds-pi-gap-now));
292	    stroke-dasharray: max(0px, var(--ds-pi-track-len) * 1px) calc(var(--ds-pi-c) * 1px);
293	    stroke-dashoffset: calc((var(--ds-pi-c) * var(--ds-pi-progress) + var(--ds-pi-gap-now)) * -1px);
294	    stroke-opacity: clamp(0, var(--ds-pi-track-len) * 1000000, 1);
295	  }
296	  /* Stepped slider dots. The active/inactive split is a plain attribute
297	   * selector rather than a Tailwind `data-[active]:` variant — variants only
298	   * compose with generated utilities, so pairing one with a class defined here
299	   * silently produced no rule and every dot stayed the inactive tone.
300	   *
301	   * The helper owns the dot's geometry too, so the highlighted step can grow
302	   * from it. ONLY `height` transitions: the colour flip stays discrete on
303	   * purpose (see the step-dot comment in Slider.tsx). The dot is centred with
304	   * a -50% translate of its own height, so it grows from its centre. */
